import math
    import random
    import time

    LANGUAGE_WRAPPER = 'If the integer $k$ is added to each of the numbers {numbers_list}, one obtains the {power_str} of {num_terms} consecutive terms of an arithmetic progression. Find $k$.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math

while True:
    m = rng.choice([3, 4])
    d = rng.choice([-5, -4, -3, -2, 2, 3, 4, 5])
    x = rng.randint(-10, 10)
    k = rng.randint(200, 2000)

    num_terms = m + 1
    ap_terms = [x + i * d for i in range(num_terms)]

    if 0 in ap_terms:
        continue

    powers = [term**m for term in ap_terms]

    # Ensure powers are within a reasonable range to avoid very large numbers in the problem statement.
    if any(abs(p) > 50000 for p in powers):
        continue

    a = [p - k for p in powers]

    # Ensure the generated problem is non-trivial.
    # The differences should not be too simple.
    if len(set(a)) < num_terms:
        continue

    # Verify that this generated problem has a unique solution for k.
    # This is a lightweight version of the verifier.
    try:
        m_fact = math.factorial(m)

        diffs = list(a)
        for i in range(m):
            diffs = [diffs[j+1] - diffs[j] for j in range(len(diffs)-1)]

        delta_m = diffs[0]
        if delta_m % m_fact != 0:
            continue

        d_m_val = delta_m // m_fact

        # Check if d_m_val is a perfect m-th power
        d_sol = int(round(abs(d_m_val)**(1/m)))
        if d_sol**m != abs(d_m_val):
            continue

        # If we got here, the parameters are likely good.
        break
    except (ValueError, OverflowError):
        continue

power_map = {
    2: "squares",
    3: "cubes",
    4: "fourth powers",
    5: "fifth powers"
}
power_str = power_map.get(m, f"{m}-th powers")

return {
    "numbers_list": ", ".join(map(str, a)),
    "num_terms": num_terms,
    "power_str": power_str,
    "_m": m,  # hidden parameter for verifier
    "_a": a   # hidden parameter for verifier
}

    def verifier(assign):
import math

m = assign["_m"]
a = assign["_a"]
num_terms = assign["num_terms"]

if len(a) != num_terms or num_terms != m + 1:
    # Malformed assignment
    return False, None

# Use finite differences to find d
# The m-th difference of a sequence P(i) = (x+(i-1)d)^m is m! * d^m
m_fact = math.factorial(m)

diffs = list(a)
for i in range(m):
    # Check for sufficient terms for next difference calculation
    if len(diffs) < 2:
        return False, None
    diffs = [diffs[j+1] - diffs[j] for j in range(len(diffs)-1)]

delta_m = diffs[0]

if delta_m % m_fact != 0:
    return False, None # d^m would not be an integer

d_m_val = delta_m // m_fact

possible_d = set()
if d_m_val == 0:
    possible_d.add(0)
else:
    root = round(abs(d_m_val)**(1/m))
    if root**m == abs(d_m_val):
        if m % 2 == 1:
            d = root if d_m_val > 0 else -root
            possible_d.add(d)
        else:
            possible_d.add(root)
            possible_d.add(-root)

if not possible_d:
    return False, None # No integer solution for d

valid_k_values = set()

for d_sol in possible_d:
    if d_sol == 0:
        continue

    # Use (m-1)-th difference to find x
    # Delta^(m-1) of P(i) at i=1 is m!*d^(m-1)*x + d^m*m!*(m-1)/2
    # x = (Delta^(m-1) a_1 / (m!*d^(m-1))) - d*(m-1)/2

    diffs_m_minus_1 = list(a)
    for i in range(m - 1):
        diffs_m_minus_1 = [diffs_m_minus_1[j+1] - diffs_m_minus_1[j] for j in range(len(diffs_m_minus_1)-1)]
    delta_m_minus_1 = diffs_m_minus_1[0]

    # Denominator for the first term of x formula
    denom = m_fact * (d_sol**(m - 1))
    if denom == 0 or delta_m_minus_1 % denom != 0:
        continue # x would not be integer or half-integer

    term1_num = delta_m_minus_1 // denom
    term2_num = d_sol * (m - 1)

    # x must be an integer
    if (term1_num % 2) != (term2_num % 2):
        continue # x is not an integer

    x_sol = (term1_num - term2_num) / 2
    if x_sol != int(x_sol):
        continue

    x_sol = int(x_sol)

    # Calculate k and verify
    k_sol = x_sol**m - a[0]

    is_valid = True
    for i in range(num_terms):
        if not math.isclose(a[i] + k_sol, (x_sol + i * d_sol)**m):
            is_valid = False
            break

    if is_valid:
        valid_k_values.add(k_sol)

if len(valid_k_values) == 1:
    return True, valid_k_values.pop()
else:
    # Fails if there is no solution or multiple solutions for k
    return False, None


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

